          { scaleX: 0 },
          { scaleX: 1, duration: 0.75, ease: "power3.out" },
          RULE_AT,
        );

        // bounded idle breathe on the hold — finite, no yoyo loop
        const phase = { p: 0 };
        const glowEl = document.getElementById("glow");
        tl.to(
          phase,
          {
            p: Math.PI * 2,
            duration: BREATHE_DUR,
            ease: "none",
            onUpdate: () => {
