<html lang="pt-BR">
  <head>
    <meta charset="UTF-8">
    <title>Tagline — Conectar Para Crescer</title>
  </head>
  <body>
    <template>
      <style>
        /* Root is styled by #root (never a class) — sub-composition contract. */
        #root {
          position: absolute;
          inset: 0;
          overflow: hidden;
          background: #04070c;
        }

        /* ── fundo fluido verde/azul ─────────────────────────────────────── */
        /* inset > 0 keeps the BoxModel inside the frame while the bloom breathes:
           a full-bleed box scaled above 1 is reported as container overflow. */
        #bg {
          position: absolute;
          inset: 24px;
          opacity: 0.5;
          filter: url(#hf-warp);
          will-change: opacity, transform;
        }
        .mesh {
          position: absolute;
          inset: 0;
          filter: blur(72px);
        }
        /* two counter-drifting layers: the mesh block's CSS-var trick, no keyframes */
        .m1 {
          background:
            radial-gradient(circle at var(--x1, 16%) var(--y1, 26%), #22d3ee 0 15%, transparent 33%),
            radial-gradient(circle at var(--x2, 80%) var(--y2, 58%), #2563eb 0 17%, transparent 36%),
            radial-gradient(circle at var(--x3, 40%) var(--y3, 86%), #10b981 0 15%, transparent 33%);
        }
        .m2 {
          mix-blend-mode: screen;
          opacity: 0.55;
          background:
            radial-gradient(circle at var(--u1, 68%) var(--v1, 12%), #14b8a6 0 13%, transparent 31%),
            radial-gradient(circle at var(--u2, 22%) var(--v2, 76%), #1d4ed8 0 15%, transparent 34%);
        }
        #vignette {
          position: absolute;
          inset: 0;
          background: radial-gradient(
            ellipse at 50% 52%,
            rgba(4, 7, 12, 0) 38%,
            rgba(4, 7, 12, 0.78) 100%
          );
        }

        /* ── ruído de filme ──────────────────────────────────────────────── */
        #grain {
          position: absolute;
          inset: 0;
          z-index: 40;
          pointer-events: none;
        }
        #grain .tex {
          position: absolute;
          inset: 0;
          opacity: 0.1;
          background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
          background-repeat: repeat;
          background-size: 256px 256px;
          will-change: background-position;
        }

        /* ── tipografia ──────────────────────────────────────────────────── */
        #stage {
          position: absolute;
          inset: 0;
          z-index: 10;
          display: flex;
          flex-direction: column;
          justify-content: center;
          padding: 0 160px;
        }
        /* Breathe the content-sized lock-up, not the full-bleed stage: a viewport-sized
           box scaled above 1 always bleeds and reads as the frame moving. */
        .lockup {
          display: flex;
          flex-direction: column;
          align-items: flex-start;
          width: 100%;
          will-change: transform;
        }
        .line {
          font-family: "Archivo Black", sans-serif;
          font-weight: 400;
          letter-spacing: -0.02em;
          line-height: 0.98;
          color: #f3f8f6;
          will-change: transform, opacity, filter;
        }
        .line-1 {
          font-size: 190px;
        }
        .line-2 {
          font-family: "JetBrains Mono", monospace;
          font-weight: 400;
          font-size: 100px;
          letter-spacing: 0.02em;
          line-height: 1.5;
          color: #8fa6a1;
        }
        .line-3 {
          font-size: 190px;
          background-image: linear-gradient(96deg, #22d3ee, #7ee39f);
          -webkit-background-clip: text;
          background-clip: text;
          color: transparent;
        }
        .rule {
          width: 100%;
          height: 8px;
          margin-top: 56px;
          border-radius: 999px;
          background-image: linear-gradient(96deg, #22d3ee, #7ee39f);
          transform: scaleX(0);
          transform-origin: 0 50%;
          will-change: transform;
        }

        /* the SVG filter itself must not take layout space */
        .filter-defs {
          position: absolute;
          width: 0;
          height: 0;
        }
      </style>

      <div data-hf-id="hf-bwsb" id="root" data-composition-id="tagline" data-width="1920" data-height="1080">
        <svg class="filter-defs" aria-hidden="true">
          <filter
            id="hf-warp"
            x="-8%"
            y="-8%"
            width="116%"
            height="116%"
            color-interpolation-filters="sRGB"
          >
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.0042 0.0075"
              numOctaves="2"
              seed="11"
              result="hf-noise"
            ></feTurbulence>
            <feDisplacementMap
              id="hf-warp-map"
              in="SourceGraphic"
              in2="hf-noise"
              scale="48"
              xChannelSelector="R"
              yChannelSelector="G"
            ></feDisplacementMap>
          </filter>
        </svg>

        <div id="bg">
          <div class="mesh m1"></div>
          <div class="mesh m2"></div>
        </div>
        <div id="vignette"></div>

        <div data-hf-id="hf-lp42" id="stage">
          <div data-hf-id="hf-9rga" class="lockup" id="lockup">
            <div data-hf-id="hf-h1pi" class="line line-1" id="p1">Conectar</div>
            <div data-hf-id="hf-f4bj" class="line line-2" id="p2">para</div>
            <div data-hf-id="hf-jdvi" class="line line-3" id="p3">Crescer</div>
            <div data-hf-id="hf-u4he" class="rule" id="rule"></div>
          </div>
        </div>

        <div id="grain"><div class="tex"></div></div>
      </div>

      <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
      <script>
        // ── one tempo grid drives every onset (kinetic-beat-slam) ──
        const DUR = 7;
        const PULSE = 0.3;
        const BEATS = [PULSE * 2, PULSE * 6, PULSE * 10]; // 0.6 / 1.8 / 3.0

        // ── the background is alive from frame 0 and blooms with the last word ──
