        const BLOOM_START = BEATS[2] + 0.55 - BLOOM_DUR;
        const BLOOM_END = BLOOM_START + BLOOM_DUR;
        const BREATHE_DUR = DUR - BLOOM_END;
        const RULE_AT = BEATS[2] + 0.65;
        const HOLD_START = BEATS[2] + 1.4;
        const HOLD_CYCLE = 1.6;
        const HOLD_DUR = DUR - HOLD_START;

        gsap.set("#p1", { x: -12.736, y: -7.061 });
        const tl = gsap.timeline({ paused: true });

        // ── fundo: dois campos em contra-deriva, um respiro de 7s sem repeat ──
        tl.fromTo(
          ".m1",
          { "--x1": "16%", "--y1": "26%", "--x2": "80%", "--y2": "58%", "--x3": "40%", "--y3": "86%" },
          { "--x1": "38%", "--y1": "46%", "--x2": "56%", "--y2": "70%", "--x3": "64%", "--y3": "62%", duration: DUR, ease: "sine.inOut" },
          0,
        );
        tl.fromTo(
          ".m2",
          { "--u1": "68%", "--v1": "12%", "--u2": "22%", "--v2": "76%" },
          { "--u1": "36%", "--v1": "54%", "--u2": "60%", "--v2": "28%", duration: DUR, ease: "sine.inOut" },
          0,
        );

        // distorção: a força do deslocamento respira (yoyo finito, termina antes de DUR)
        tl.fromTo(
          "#hf-warp-map",
          { attr: { scale: 44 } },
          { attr: { scale: 92 }, duration: 3.2, ease: "sine.inOut", yoyo: true, repeat: 0 },
          0.4,
        );

        // grão de filme: um único tween em degraus — determinístico ao seek
        tl.fromTo(
          "#grain .tex",
          { backgroundPosition: "0px 0px" },
          { backgroundPosition: "-416px 288px", duration: DUR, ease: "steps(28)" },
          0,
        );

        // #p1 — scale + blur slam (hardest hit)
        tl.fromTo(
          "#p1",
          { scale: 1.42, filter: "blur(18px)", opacity: 0 },
          { scale: 1, filter: "blur(0px)", opacity: 1, duration: 0.5, ease: "power4.out" },
          BEATS[0],
        );

        // #p2 — side snap; the connector arrives quietly
        tl.fromTo(
          "#p2",
          { x: -210, opacity: 0 },
          { x: 0, opacity: 1, duration: 0.45, ease: "expo.out" },
          BEATS[1],
        );

        // #p3 — rise with momentum
        tl.fromTo(
          "#p3",
          { y: 104, rotation: 5, opacity: 0 },
          { y: 0, rotation: 0, opacity: 1, duration: 0.55, ease: "circ.out" },
          BEATS[2],
        );

        // the field lights up behind the lock-up, resolving together with #p3
        tl.fromTo(
          "#bg",
          { opacity: BG_DIM, scale: 1.03 },
          { opacity: BG_PEAK, scale: 1, duration: BLOOM_DUR, ease: "power2.out" },
          BLOOM_START,
        );

        // finale dressing: accent rule sweeps across the column
        tl.fromTo(
          "#rule",
          { scaleX: 0 },
          { scaleX: 1, duration: 0.75, ease: "power3.out" },
          RULE_AT,
        );

