        const phase = { p: 0 };
        const bgEl = document.getElementById("bg");
        tl.to(
          phase,
          {
            p: Math.PI * 2,
            duration: BREATHE_DUR,
            ease: "none",
            onUpdate: () => {
              const s = Math.sin(phase.p);
              bgEl.style.opacity = String(BG_PEAK + s * 0.05);
              bgEl.style.transform = `scale(${1 + s * 0.012})`;
            },
          },
          BLOOM_END,
        );

