        tl.to(
          "#lockup",
          {
            scale: 1.01,
            duration: HOLD_CYCLE / 2,
            ease: "sine.inOut",
            yoyo: true,
            repeat: Math.max(0, Math.floor(HOLD_DUR / HOLD_CYCLE) - 1),
          },
          HOLD_START,
        );

        window.__timelines["tagline"] = tl;
      </script>
    </template>
  </body>
</html>
